package test;

import org.eclipse.ui.PlatformUI;
import org.eclipse.ui.plugin.AbstractUIPlugin;
import org.osgi.framework.BundleContext;

public class MyPlugin extends AbstractUIPlugin {
    private static MyPlugin plugin;

    public MyPlugin() {
        plugin = this;
    }

    public static MyPlugin getDefault() {
        return plugin;
    }

    @Override
    public void start(BundleContext context) throws Exception {
        super.start(context);
        // Scenario 1: Access via static getDefault()
        getDefault().getWorkbench().getWorkbenchWindows();
        // Scenario 2: Access via 'this'
        this.getWorkbench().getActiveWorkbenchWindow();
        // Scenario 3: Access via a field or local variable
        MyPlugin instance = getDefault();
        instance.getWorkbench().getEditorRegistry();
    }
}

