        super.start(context);
        // Scenario 1: Access via static getDefault()
        org.eclipse.ui.PlatformUI.getWorkbench().getWorkbenchWindows();
        // Scenario 2: Access via 'this'
        org.eclipse.ui.PlatformUI.getWorkbench().getActiveWorkbenchWindow();
